function aeogeoApprovedHomepageGraph(){j.useEffect(()=>{const paused=[];let script=document.getElementById("aeogeo-homepage-schema");for(const el of document.head.querySelectorAll('script[type="application/ld+json"]')){if(el!==script){paused.push(el);el.type="application/x-aeogeo-suspended+json";}}if(!script){script=document.createElement("script");script.id="aeogeo-homepage-schema";script.type="application/ld+json";document.head.appendChild(script);}script.textContent="{\"@context\":\"https://schema.org\",\"@graph\":[{\"@type\":\"ProfessionalService\",\"@id\":\"https://aeogeosearch.com/#organization\",\"name\":\"AEOGEO Search\",\"url\":\"https://aeogeosearch.com/\",\"description\":\"AI search optimization, AEO, GEO, AIO and SEO services for businesses nationwide.\",\"telephone\":\"+1-469-905-2836\",\"email\":\"aeogeosearch@atomicmail.io\",\"address\":{\"@type\":\"PostalAddress\",\"addressLocality\":\"McKinney\",\"addressRegion\":\"TX\",\"postalCode\":\"75072\",\"addressCountry\":\"US\"},\"areaServed\":{\"@type\":\"Country\",\"name\":\"United States\"},\"founder\":{\"@type\":\"Person\",\"name\":\"Michelle S.\"},\"hasOfferCatalog\":{\"@id\":\"https://aeogeosearch.com/#offer-catalog\"},\"logo\":\"https://aeogeosearch.com/images/aeogeo-header-logo.png\"},{\"@type\":\"WebSite\",\"@id\":\"https://aeogeosearch.com/#website\",\"url\":\"https://aeogeosearch.com/\",\"name\":\"AEOGEO Search\",\"publisher\":{\"@id\":\"https://aeogeosearch.com/#organization\"},\"inLanguage\":\"en-US\"},{\"@type\":\"WebPage\",\"@id\":\"https://aeogeosearch.com/#webpage\",\"url\":\"https://aeogeosearch.com/\",\"name\":\"AEO, GEO & SEO Agency | Dallas-Fort Worth & Nationwide\",\"description\":\"Dallas-Fort Worth and nationwide AEO, GEO and SEO agency. AI search optimization, generative engine optimization, answer engine optimization and AI visibility. Free 25-page GEO audit or managed plans from $349/mo.\",\"dateModified\":\"2026-11-01\",\"isPartOf\":{\"@id\":\"https://aeogeosearch.com/#website\"},\"about\":{\"@id\":\"https://aeogeosearch.com/#organization\"},\"publisher\":{\"@id\":\"https://aeogeosearch.com/#organization\"},\"inLanguage\":\"en-US\",\"hasPart\":{\"@id\":\"https://aeogeosearch.com/#faq\"}},{\"@type\":\"OfferCatalog\",\"@id\":\"https://aeogeosearch.com/#offer-catalog\",\"name\":\"Free DIY audit and fixed-price AEOGEO Search services\",\"itemListElement\":[{\"@type\":\"Offer\",\"@id\":\"https://aeogeosearch.com/#offer-free-audit\",\"name\":\"Free DIY GEO Website Audit\",\"url\":\"https://aeogeosearch.com/geo-audit/\",\"price\":\"0\",\"priceCurrency\":\"USD\",\"description\":\"One free audit per verified account, up to 25 accessible pages. No implementation service or automatic subscription.\",\"seller\":{\"@id\":\"https://aeogeosearch.com/#organization\"},\"itemOffered\":{\"@type\":\"Service\",\"name\":\"Free DIY GEO Website Audit\",\"provider\":{\"@id\":\"https://aeogeosearch.com/#organization\"}}},{\"@type\":\"Offer\",\"@id\":\"https://aeogeosearch.com/#offer-starter\",\"name\":\"AI Visibility Starter\",\"url\":\"https://aeogeosearch.com/pricing#monthly-ai-search\",\"price\":\"349\",\"priceCurrency\":\"USD\",\"description\":\"Up to 2 existing pages, 4 social posts, selected AI prompt and brand-mention reviews, monthly summary and next steps.\",\"seller\":{\"@id\":\"https://aeogeosearch.com/#organization\"},\"itemOffered\":{\"@type\":\"Service\",\"name\":\"AI Visibility Starter\",\"provider\":{\"@id\":\"https://aeogeosearch.com/#organization\"}},\"priceSpecification\":{\"@type\":\"UnitPriceSpecification\",\"price\":\"349\",\"priceCurrency\":\"USD\",\"unitText\":\"month\"}},{\"@type\":\"Offer\",\"@id\":\"https://aeogeosearch.com/#offer-growth\",\"name\":\"AI Search Growth\",\"url\":\"https://aeogeosearch.com/pricing#monthly-ai-search\",\"price\":\"649\",\"priceCurrency\":\"USD\",\"description\":\"Up to 4 existing pages, 1 article of 700-1,000 words, 8 social posts, customer question research and monthly reporting.\",\"seller\":{\"@id\":\"https://aeogeosearch.com/#organization\"},\"itemOffered\":{\"@type\":\"Service\",\"name\":\"AI Search Growth\",\"provider\":{\"@id\":\"https://aeogeosearch.com/#organization\"}},\"priceSpecification\":{\"@type\":\"UnitPriceSpecification\",\"price\":\"649\",\"priceCurrency\":\"USD\",\"unitText\":\"month\"}},{\"@type\":\"Offer\",\"@id\":\"https://aeogeosearch.com/#offer-authority\",\"name\":\"AI Search Authority\",\"url\":\"https://aeogeosearch.com/pricing#monthly-ai-search\",\"price\":\"999\",\"priceCurrency\":\"USD\",\"description\":\"Up to 4 existing pages, 2 articles of 700-1,200 words each, 12 social posts, competitor gaps, a content calendar and expanded reporting.\",\"seller\":{\"@id\":\"https://aeogeosearch.com/#organization\"},\"itemOffered\":{\"@type\":\"Service\",\"name\":\"AI Search Authority\",\"provider\":{\"@id\":\"https://aeogeosearch.com/#organization\"}},\"priceSpecification\":{\"@type\":\"UnitPriceSpecification\",\"price\":\"999\",\"priceCurrency\":\"USD\",\"unitText\":\"month\"}},{\"@type\":\"Offer\",\"@id\":\"https://aeogeosearch.com/#offer-knowledge-base\",\"name\":\"Knowledge Base Package\",\"url\":\"https://aeogeosearch.com/pricing#knowledge-base\",\"price\":\"1500\",\"priceCurrency\":\"USD\",\"description\":\"50 articles, basic search functionality, one revision round and one hour of training. One-time service.\",\"seller\":{\"@id\":\"https://aeogeosearch.com/#organization\"},\"itemOffered\":{\"@type\":\"Service\",\"name\":\"Knowledge Base Package\",\"provider\":{\"@id\":\"https://aeogeosearch.com/#organization\"}}}]},{\"@type\":\"FAQPage\",\"@id\":\"https://aeogeosearch.com/#faq\",\"url\":\"https://aeogeosearch.com/#frequently-asked-questions\",\"isPartOf\":{\"@id\":\"https://aeogeosearch.com/#webpage\"},\"mainEntity\":[{\"@type\":\"Question\",\"name\":\"How does the AEOGEO Search Optimization process work?\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"We start with a complimentary 25-page DIY website GEO audit or a consultation where we evaluate how search engines and AI platforms understand your website currently. In case of a full-service plan or a project, we agree on the scope and price of the work before starting, and track our progress according to the monthly indicators and reporting included in the plan.\"}},{\"@type\":\"Question\",\"name\":\"What is AI Search Optimization?\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"AI search optimization is an approach to optimizing your website, content, technical and structured data markup, and digital presence in order for AI and generative platforms (such as ChatGPT, Google AI Overviews, Google Gemini, Perplexity, and Claude) to discover, understand, and reference your business in generated answers. At AEOGEO Search, it combines four pillars: AI Optimization (AIO), Generative Engine Optimization (GEO), Answer Engine Optimization (AEO), and Search Engine Optimization (SEO). Learn more at /resources/what-is-ai-search-optimization/.\"}},{\"@type\":\"Question\",\"name\":\"How is AI search optimization different from traditional SEO?\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"Traditional SEO focuses on ranking web pages in search engine results so users click through to your site. AI search optimization builds on that foundation by structuring clear entity facts, direct answers, and supporting evidence so AI systems cite and recommend your business inside synthesized answers. Both work together. Strong SEO remains essential because many AI search tools retrieve from traditional web indexes. Compare all four pillars at /resources/seo-aeo-geo-aio-difference/.\"}},{\"@type\":\"Question\",\"name\":\"What is GEO (Generative Engine Optimization), and how does it relate to AEO?\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"Generative Engine Optimization (GEO) structures your website's facts, context, and authority signals so generative AI engines can verify what you do, who you serve, and why customers trust you when synthesizing multi-source recommendations. Answer Engine Optimization (AEO) focuses on formatting clear, concise answers to specific buyer questions. Used together, AEO and GEO improve both passage extraction and brand citation readiness.\"}},{\"@type\":\"Question\",\"name\":\"Will my business be guaranteed to show up in ChatGPT, Google Gemini, Claude, and Perplexity?\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"No legitimate agency can guarantee placement or citations in AI-generated answers, because AI models generate dynamic responses that vary by user prompt, location, and model updates. However, you can meaningfully improve your readiness by ensuring AI crawlers can access your site, structuring clear answers and JSON-LD schema, and maintaining consistent business facts across your digital presence.\"}},{\"@type\":\"Question\",\"name\":\"How long does it take to see progress from AI search optimization?\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"There is no fixed timeframe or guaranteed placement. Progress depends on your industry, competitive landscape, current website health, content depth, and how frequently search engines and AI platforms recrawl your domain. We agree the exact monthly or project deliverables upfront and track progress against the visibility and content indicators included in your plan.\"}},{\"@type\":\"Question\",\"name\":\"How much does AI search optimization cost at AEOGEO Search?\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"Our managed full-service monthly plans are $349/month (AI Visibility Starter), $649/month (AI Search Growth), and $999/month (AI Search Authority). We also offer standalone page optimization ($150-$250/page), new SEO and AI-ready articles ($175-$300/article), workflow automation ($499-$1,499 setup; $99-$249/mo monitoring), content repurposing ($400+), custom websites, and a 50-article Knowledge Base Package ($1,500 one-time) on /pricing. For DIY teams, we offer one free 25-page Website GEO Audit per verified account, plus our free self-reported AI Visibility Snapshot checklist.\"}},{\"@type\":\"Question\",\"name\":\"Do I still need traditional SEO and Local SEO if I invest in AI search?\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"Yes. Traditional organic search and local map packs still drive the majority of high-intent website traffic, and AI search assistants frequently pull live citations from Google and Bing search indexes. Our AEOM framework combines AIO, GEO, AEO, and SEO so your business stays competitive across both traditional rankings and AI-generated recommendations.\"}},{\"@type\":\"Question\",\"name\":\"How do you measure AI search visibility?\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"We review observable search and AI visibility indicators, including how your brand appears across selected commercial AI prompts, your website's coverage of priority customer questions, technical readiness checks, and traditional organic search signals. Full-service plan clients receive a clear monthly summary detailing work completed, observed indicators, and practical next-step recommendations.\"}},{\"@type\":\"Question\",\"name\":\"Who benefits most from AEOGEO Search, and do you work with businesses outside Texas?\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"Yes, while we are based in McKinney, Texas (Dallas-Fort Worth), we serve businesses nationwide across all 50 states. Our services are built for local service providers competing in crowded markets (home services, healthcare, legal, financial, automotive, hospitality), e-commerce brands competing for category recommendations, B2B and SaaS companies whose buyers research via AI assistants, multi-location operators, and lean marketing teams needing affordable execution.\"}},{\"@type\":\"Question\",\"name\":\"What is the difference between the Free 25-Page GEO Audit and the Free AI Visibility Snapshot?\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"The Free Website GEO Audit crawls up to 25 accessible pages of your website across 22 technical, content, AI-readiness, and trust checks (one free audit per verified account, no credit card required). By contrast, the Free AI Visibility Snapshot is a quick, self-reported readiness checklist based on your answers. It does not scan your website, compare competitors, or measure live AI answer visibility.\"}},{\"@type\":\"Question\",\"name\":\"Do you offer free DIY tools like a robots.txt generator or GEO content checker?\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"Yes. Our Free Robots.txt Generator lets you configure search and AI crawler access preferences (GPTBot, ClaudeBot, PerplexityBot, Googlebot), preview rules, and download a robots.txt file for developer review before publishing (note: robots.txt is not a security barrier and the tool does not upload changes to your server). You can also test individual page copy using our Free GEO Content Checker.\"}}]}]}";return()=>{if(script.isConnected)script.remove();for(const el of paused)if(el.isConnected&&el.type==="application/x-aeogeo-suspended+json")el.type="application/ld+json";};},[]);return null;}
